// pasrt.js — language-level support for code generated by tools/pas2js.py.
// Reimplements the behaviour of the Turbo Pascal 3.0x (1985) runtime routines the program uses,
// as determined by testing against the original runtime (see README.md). Strings are JS strings of
// byte-valued chars; integers are 16-bit; reals are JS numbers that always hold exact 6-byte
// "Real48" values.

export class RunError extends Error {
  // kind 1 = I/O error, 2 = run-time error (as the 1985 runtime); code = TP3 error number;
  // pc = address of the failing call in the original program (printed as 'PC=xxxx')
  constructor(kind, code, pc) {
    super((kind === 1 ? 'I/O error ' : 'Run-time error ') + code.toString(16));
    this.kind = kind; this.code = code; this.pc = pc || 0;
  }
}

// ---------------------------------------------------------------------------- integers
export const w = (x) => (x << 16) >> 16;
export function idiv(a, b) { return w(Math.trunc(a / b)); }
export function imod(a, b) { return w(a % b); }

// ---------------------------------------------------------------------------- strings
function clampCount(n) { n = w(n); if (n < 0) return 0; if (n > 255) return 255; return n; }
function checkIndex(i, pc) { i = w(i); if (i < 1 || i > 255) throw new RunError(2, 0x11, pc); return i; }

export function cat(a, b, pc) {
  if (a.length + b.length > 255) throw new RunError(2, 0x10, pc);
  return a + b;
}
export function copy(s, index, count, pc) {
  const n = clampCount(count);
  const i = checkIndex(index, pc);
  if (s.length <= i - 1) return '';
  return s.substr(i - 1, n);
}
export function pos(sub, s) {
  if (sub.length > s.length) return 0;
  if (sub.length === 0) return 1;
  return s.indexOf(sub) + 1;
}
// Delete is implemented by the runtime itself with Copy/Concat calls; errors report the address of
// those internal calls (1985 runtime: Copy at 144A and 1464, Concat at 1467).
export function del(s, index, count) {
  const head = copy(s, 1, w(index - 1), 0x144A);
  const j = w(index + count);
  if (j < 0 || j > 255) return head;
  return cat(head, copy(s, j, 255, 0x1464), 0x1467);
}
export function ins(src, s, index) {
  const i = checkIndex(index);
  const r = s.substr(0, i - 1) + src + s.substr(i - 1);
  return r.length > 255 ? r.substr(0, 255) : r;
}
export function upcase(c) { return (c >= 0x61 && c <= 0x7a) ? c - 0x20 : c; }
export function strchar(s, pc) { if (s.length !== 1) throw new RunError(2, 0x10, pc); return s.charCodeAt(0); }
export function inset(x, items) {
  for (const it of items) {
    if (Array.isArray(it)) { if (x >= it[0] && x <= it[1]) return 1; }
    else if (x === it) return 1;
  }
  return 0;
}
export function strInt(v, width) {
  let s = String(w(v));
  while (s.length < width) s = ' ' + s;
  return s;
}
// Val(s, v, code) for an integer v: returns [newValue, code]; the variable keeps `old` if the
// runtime would not store a value.
export function valInt(s, old) {
  const buf = s.substr(0, 127);
  if (buf.length === 0) return [old, 0];
  let i = 0;
  const neg = buf.charCodeAt(0) === 0x2d;
  if (neg) i++;
  let base = 10, acc = 0, err = false;
  if (buf.charCodeAt(i) === 0x24) { base = 16; i++; }
  for (; i < buf.length; i++) {
    let c = upcase(buf.charCodeAt(i)) - 0x30;
    if (c < 0) break;
    if (c >= 10) {
      if (base !== 16) break;
      c -= 7;
      if (c < 10 || c >= 16) break;
    }
    acc = acc * base;
    if (acc > 0xffff) { err = true; break; }
    acc += c;
    if (acc > 0xffff) { err = true; break; }
  }
  if (!err && base === 10 && acc >= 0x8000) err = !(acc === 0x8000 && neg);
  if (err) return [old, i + 1];
  let v = neg ? -acc : acc;
  v = w(v);
  return [v, i >= buf.length ? 0 : i + 1];
}

// ---------------------------------------------------------------------------- base64
export function b64(s) {
  if (typeof atob === 'function') {
    const bin = atob(s); const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }
  return new Uint8Array(Buffer.from(s, 'base64'));
}

// ---------------------------------------------------------------------------- Real48 arithmetic
// Real48: value = (1 + m/2^39) * 2^(e-129), sign in the top mantissa bit, e = 0 means zero.
// The 1985 runtime truncates: products and quotients are the exact result truncated to the
// 40-bit significand; for addition/subtraction the operand with the smaller exponent is shifted
// right (truncating) before the add, then the sum is normalised and truncated.

const B40 = 1n << 40n, B39 = 1n << 39n;

// decompose a double holding an exact Real48 value: returns [sign, m (BigInt in [2^39,2^40)), e]
// with value = sign * m * 2^(e-39)
function split(x) {
  const s = x < 0 ? -1 : 1; x = Math.abs(x);
  let e = Math.floor(Math.log2(x));
  if (Math.pow(2, e) > x) e--; else if (Math.pow(2, e + 1) <= x) e++;
  // m = x * 2^(39-e) exactly (x has at most 40 significant bits)
  const m = BigInt(Math.round(x * Math.pow(2, 39 - e)));
  return [s, m, e];
}
function make(s, m, e) {
  // m: BigInt >= 0 with arbitrary bits, value = m * 2^(e) ; normalise to 40 bits by truncation
  if (m === 0n) return 0;
  let bits = m.toString(2).length;
  if (bits > 40) { const sh = BigInt(bits - 40); m = m >> sh; e += bits - 40; }
  else if (bits < 40) { const sh = BigInt(40 - bits); m = m << sh; e -= 40 - bits; }
  return s * Number(m) * Math.pow(2, e);
}
export function r48(e, m0, m1, m2, m3, m4) {
  if (e === 0) return 0;
  const neg = (m4 & 0x80) !== 0;
  const m = BigInt(m0) | (BigInt(m1) << 8n) | (BigInt(m2) << 16n) | (BigInt(m3) << 24n) | (BigInt(m4 & 0x7f) << 32n);
  const v = Number(B39 | m) * Math.pow(2, e - 129 - 39);
  return neg ? -v : v;
}
// round an arbitrary JS number (e.g. an integer) to Real48 by truncation (exact for |int| < 2^40)
export function toReal(x) {
  if (x === 0) return 0;
  return x;
}
export function rmul(a, b) {
  if (a === 0 || b === 0) return 0;
  const [sa, ma, ea] = split(a), [sb, mb, eb] = split(b);
  return make(sa * sb, ma * mb, ea + eb - 78);
}
export function rdiv(a, b) {
  if (b === 0) throw new RunError(2, 0x02);   // division by zero
  if (a === 0) return 0;
  const [sa, ma, ea] = split(a), [sb, mb, eb] = split(b);
  const K = 64n;
  return make(sa * sb, (ma << K) / mb, ea - eb - 64);
}
function addsub(a, b) {
  if (a === 0) return b;
  if (b === 0) return a;
  let [sx, mx, ex] = split(a), [sy, my, ey] = split(b);
  if (ex < ey || (ex === ey && mx < my)) { [sx, mx, ex, sy, my, ey] = [sy, my, ey, sx, mx, ex]; }
  const d = BigInt(ex - ey);
  const MY = d >= 64n ? 0n : (my >> d);
  let r = BigInt(sx) * mx + BigInt(sy) * MY;
  if (r === 0n) return 0;
  const s = r < 0n ? -1 : 1;
  if (r < 0n) r = -r;
  return make(s, r, ex - 39);
}
export function radd(a, b) { return addsub(a, b); }
export function rsub(a, b) { return addsub(a, -b); }
export function rneg(a) { return -a; }
export function rcmp(a, b, op) {
  switch (op) {
    case '=': return a === b; case '<>': return a !== b;
    case '<': return a < b; case '>': return a > b;
    case '<=': return a <= b; case '>=': return a >= b;
  }
}
export function trunc(x) { return w(Math.trunc(x)); }
export function round(x) { return w(x >= 0 ? Math.floor(x + 0.5) : -Math.floor(-x + 0.5)); }

// encode/decode for memory (6 bytes)
export function encodeReal(x) {
  const b = new Uint8Array(6);
  if (x === 0) return b;
  const [s, m, e] = split(x);
  b[0] = e + 129;
  let mm = m - B39;
  for (let i = 1; i <= 5; i++) { b[i] = Number(mm & 0xffn); mm >>= 8n; }
  if (s < 0) b[5] |= 0x80;
  return b;
}
export function decodeReal(b) { return r48(b[0], b[1], b[2], b[3], b[4], b[5]); }
